css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .8); height: var(--loader-size); position: relative; perspective: 500px; }
.loader span { position: absolute; inset: 0; border-radius: 14%; background: linear-gradient(135deg, var(--accent), var(--accent-2)); transform-origin: center top; animation: flip calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .28); opacity: .78; }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .56); opacity: .55; }
@keyframes flip { 0%, 55%, 100% { transform: rotateX(0deg); } 28% { transform: rotateX(-172deg); } }
